# blender -b -P tools/export_appearances.py -- extract/ue/appearances/jobs.json
#
# Exports the equipment appearances for Unreal (list generated by tools/convert_appearances.py):
#   body:   one base body part of player_male.cdf (head1, shirt1, gloves1, pants1, boots1) -> Body/SK_body_<key>
#   armor:  one armor appearance (nwbt armorappearances/<ID>-skin1.glb, Skin1 + AppearanceCDF cloth) -> Armor/SK_<ID>
#   weapon: one weapon appearance (nwbt glb of the MeshOverride .cdf) -> Weapons/SM_<ID>
# Each output folder holds <name>.fbx, textures/ and materials.json (the import_npcs.py format).
#
# Skinned parts are exported exactly like SK_player_male (tools/export_ue.py): the same player glb goes through
# nwchar.import_character, the piece goes onto that skeleton with nwchar.attach_armor, and nwchar.to_centimeters
# scales mesh and skeleton (no scale left on object or bone). Same bind pose and bone names, so the meshes go
# onto the existing SK_player_male skeleton and follow it with SetLeaderPoseComponent.
# Weapons follow export_ue.py: glb imported in an empty scene, meshes only, origin at the grip point.
import json
import os
import sys

import bpy

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import nwchar  # noqa: E402

FBX_COMMON = dict(use_selection=True, add_leaf_bones=False, apply_unit_scale=True,
                  apply_scale_options="FBX_SCALE_NONE", mesh_smooth_type="FACE", use_armature_deform_only=False,
                  bake_anim=False, path_mode="COPY", embed_textures=True)
BODY_PARTS = {"head1", "shirt1", "shirt2", "gloves1", "pants1", "boots1", "xray", "Icosphere"}


def select_only(objs):
    bpy.ops.object.select_all(action="DESELECT")
    for o in objs:
        o.select_set(True)
    bpy.context.view_layer.objects.active = objs[0]


def player(glb, keep=None):
    """Player skeleton from the same glb as SK_player_male; keeps only the body part `keep` (or none)."""
    bpy.ops.wm.read_factory_settings(use_empty=True)
    arm = nwchar.import_character(glb, drop=BODY_PARTS - {keep})
    arm.name = "Armature"  # Unreal drops the armature object as root bone only with this name
    # The set's glb carries the clips: they only pick the skeleton copy. The meshes are exported at rest.
    nwchar.reset_pose(arm)
    arm.animation_data_clear()
    for act in list(bpy.data.actions):
        bpy.data.actions.remove(act)
    # Dropped body parts leave their materials and images behind: flatten_materials would write them
    # into every armor folder.
    bpy.data.orphans_purge(do_local_ids=True, do_linked_ids=True, do_recursive=True)
    return arm


def export(out, name, objs, types, materials):
    os.makedirs(out, exist_ok=True)
    select_only(objs)
    bpy.ops.export_scene.fbx(filepath=os.path.join(out, name + ".fbx"), object_types=types, **FBX_COMMON)
    json.dump(materials, open(os.path.join(out, "materials.json"), "w"), indent=1)


jobs_path = sys.argv[sys.argv.index("--") + 1]
jobs = json.load(open(jobs_path))
failed = []
for job in jobs:
    out = job["out"]
    try:
        if job["kind"] == "body":
            arm = player(job["player_glb"], job["part"])
            meshes = [o for o in bpy.context.scene.objects if o.type == "MESH" and o.parent == arm]
            if not meshes:
                raise RuntimeError(f"part {job['part']} not in the glb")
        elif job["kind"] == "armor":
            arm = player(job["player_glb"])
            meshes, _ = nwchar.attach_armor(arm, job["glb"])
            if not meshes:
                raise RuntimeError("no mesh in the glb")
        else:
            bpy.ops.wm.read_factory_settings(use_empty=True)
            bpy.ops.import_scene.gltf(filepath=job["glb"])
            meshes = [o for o in bpy.context.scene.objects if o.type == "MESH"]
            if not meshes:
                raise RuntimeError("no mesh in the glb")
            materials = nwchar.flatten_materials(os.path.join(out, "textures"))
            export(out, job["name"], meshes, {"MESH"}, materials)
            print(f"APPEARANCE {job['name']}: {len(meshes)} meshes, {len(materials)} materials")
            continue
        nwchar.to_centimeters(arm, meshes)
        materials = nwchar.flatten_materials(os.path.join(out, "textures"))
        export(out, job["name"], [arm] + meshes, {"ARMATURE", "MESH"}, materials)
        parts = ", ".join(sorted(nwchar.base(o.name) for o in meshes))
        print(f"APPEARANCE {job['name']}: {len(meshes)} meshes ({parts}), {len(materials)} materials")
    except Exception as exc:  # one broken appearance must not stop the others; the caller checks the outputs
        failed.append(job["name"])
        print(f"APPEARANCE FAILED {job['name']}: {exc}")
print(f"export_appearances: {len(jobs) - len(failed)}/{len(jobs)} exported; failed: {failed}")
